<script>
(() => {
  'use strict';
  const ns = 'http://www.w3.org/2000/svg', by = id => document.getElementById(id);
  const el = (name, attrs, parent) => {
    const n = document.createElementNS(ns, name);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    parent.appendChild(n); return n;
  };
  let seed = 8381;
  const rnd = () => ((seed = (Math.imul(seed,1664525)+1013904223)>>>0) / 4294967296);
  const pick = a => a[Math.floor(rnd()*a.length)];
  const f = n => +n.toFixed(2), tau = Math.PI*2;
  const use = (parent,id,x,y,s,c,lean=0) => el('use',{href:'#'+id, transform:`translate(${f(x)} ${f(y)}) skewX(${f(lean)}) scale(${f(s)})`,fill:c},parent);

  // Tiny irregular ink marks are generated once, never randomized between frames.
  for (let i=0;i<154;i++){
    const x=rnd()*1280,y=443+rnd()*56,s=.055+.16*(y-438)/62*rnd();
    use(by('pastureDetails'),'grass',x,y,s,pick(['#929a77','#aa9c73','#dcca97']),-12);
    if(i%4===0) el('path',{d:`M${f(x)} ${f(y+1)}q9-2 23 0-13-1-23 0`,fill:'#a79f7c'},by('pastureDetails'));
  }
  for(let i=0;i<162;i++){
    const x=rnd()*1280,y=507+rnd()*92,w=1+rnd()*10;
    el('path',{d:`M${f(x)} ${f(y)}q${f(w*.3)} ${f(-1-rnd()*2)} ${f(w)} -.5l${f(w*.5)} 1Z`, fill:pick(['#b38964','#f7dcad','#c29b72','#d2ab80']),opacity:f(.4+rnd()*.4)},by('trailDetails'));
  }
  for(let i=0;i<122;i++){
    const x=rnd()*1280,y=597+9*Math.sin(tau*x/1280*2)+rnd()*36;
    use(by('bankGrass'),'grass',x,y,.19+rnd()*.39,pick(['#b6a675','#9d9970','#caba85','#a59e73']),-14+rnd()*12);
  }
  for(let i=0;i<48;i++){
    const x=7+rnd()*1265,y=635-6*Math.sin(x*tau/1280*3)+rnd()*4;
    use(by('frontGrass'),'grass',x,y,.49+rnd()*.54,pick(['#75846b','#859071','#a19b71','#647d68']),-8+rnd()*18);
    if(i%4===0) use(by('frontGrass'),'plume',x+3,y,.59+rnd()*.38,'none',-14);
  }
  for(let i=0;i<76;i++){
    const x=rnd()*1280,y=640+rnd()*72,w=3+rnd()*18;
    el('path',{d:`M${f(x)} ${f(y)}q${f(w*.4)} -2 ${f(w)} -1`,fill:'none',stroke:'#aac09c','stroke-width':1,opacity:f(.08+rnd()*.15)},by('frontMarks'));
  }
  // Broken crescent marks follow the fleece rather than outlining every curl.
  for(let i=0;i<146;i++){
    const neck=i>91;
    const x=neck?52+rnd()*65:-125+rnd()*231, y=neck?-303+rnd()*115:-223+rnd()*99;
    const s=.55+rnd()*.65;
    el('path',{d:pick(['M-4-1q3 5 7 0','M-4 0q1 4 5 3 3 1 4-2','M-3 1q2 2 5-1']),transform:`translate(${f(x)} ${f(y)}) rotate(${f((neck?-26:0)+rnd()*34-17)}) scale(${f(s)})`,stroke:rnd()<.48?'#fff8df':'#b89876','stroke-width':f(1.1+rnd()*.95),opacity:f(.25+rnd()*.33)},by('curls'));
  }
  for(let i=0;i<15;i++){
    const a=i/14,x=-78+91*a,y=(1-a)*(1-a)*-168+2*a*(1-a)*-157+a*a*-176;
    el('path',{d:`M${f(x)} ${f(y-2)}q1 4 ${f(1.4+rnd()*2)} ${f(6+rnd()*2)}`,stroke:i%3===0?'#b7593f':'#e6c28a','stroke-width':3},by('fringe'));
  }
  for(let i=0;i<7;i++){
    const x=-90+i*19,y=-196+1.6*Math.sin(i/6*Math.PI);
    el('path',{d:`M${x-9} ${y}l4-2v-2h3v-3h4v3h3v2l4 2-4 2v2h-3v3h-4v-3h-3v-2Z`,fill:'#efc68c'},by('diamonds'));
    el('path',{d:`M${x-3} ${y}l3-3 3 3-3 3Z`,fill:'#b95841'},by('diamonds'));
  }

  // Four independent feet: constant ground speed in stance; eased recovery.
  // The front carpus folds forward, while the rear hock folds backward.
